
import './cloud-sync.js?v=family2';
import{PILOT_CHAIN,createBlankLearner}from'./pilot-data.js';
const pilotKey='mathlab-pilot-v1',learnerKey='mathlab-portal-learner',rewardKey='mathlab-portal-rewards';
const milestones=[50,100,200,400,700,1000],defaults=['Choose a family reward','Pick the family movie','Choose Saturday breakfast','Plan a mini adventure','Choose a new book or game','Design a family celebration'];
const creditByMission={'starting-point':10,'equal-groups':20,'split-array':20,'fact-family':20,'fresh-transfer':30};
const courses=[['01','Multiplication as Equal Groups','pilot.html','ready'],['02','Fractions','fraction.html'],['03','Place Value','place.html'],['04','Addition & Subtraction','addition.html'],['05','Patterns & Algebra','patterns.html'],['06','Geometry & Space','geometry.html'],['07','Measurement','measurement.html'],['08','Data Reasoning','datareason.html'],['09','Mathematical Modeling','modeling.html'],['10','Money & Decisions','money.html'],['11','Number Logic','numberlogic.html'],['12','Visual Patterns','visualpatterns.html'],['13','Spatial Thinking','spatial.html'],['14','Language & Logic','logic.html'],['15','Division & Remainders','division.html'],['16','Multiply by Breaking Apart','multiply.html'],['17','Factor Detective','factors.html'],['18','Smart Multiplication Moves','properties.html'],['19','Fraction Benchmark Lab','benchmark.html'],['20','Fraction Addition Sense','fractionops.html']];
let learner=localStorage.getItem(learnerKey)||'a';
const $=s=>document.querySelector(s);
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}
function state(){return(read(pilotKey,{a:createBlankLearner(),b:createBlankLearner()})[learner]||createBlankLearner())}
function rewards(){const x=read(rewardKey,{});return milestones.map((credits,i)=>({credits,name:x[credits]||defaults[i]}))}
function render(){const s=state(),done=Object.values(s.missions||{}).filter(x=>x.complete).length,total=Object.entries(creditByMission).reduce((n,[id,v])=>n+(s.missions?.[id]?.complete?v:0),0),name=learner==='a'?'Ella':'Mila';$('#creditTotal').textContent=total;$('#completedCount').textContent=done+' of 5 ready-path missions';$('#progressTitle').textContent=name+'’s current path';$('#missionSteps').innerHTML=PILOT_CHAIN.missions.map((m,i)=>{const ok=Boolean(s.missions?.[m.id]?.complete),ready=i===0||Boolean(s.missions?.[PILOT_CHAIN.missions[i-1]?.id]?.complete);return '<div class="mission-step '+(ok?'done':ready?'ready':'')+'"><b>'+(ok?'✓ ':ready?'▶ ':'○ ')+m.number+'. '+m.title+'</b><span>'+(ok?'Completed':ready?'Ready':'Locked')+'</span></div>'}).join('');$('#rewardForm').innerHTML=rewards().map(r=>'<label class="reward-input"><strong>'+r.credits+' ★</strong><input data-reward="'+r.credits+'" value="'+r.name.replaceAll('&','&amp;').replaceAll('"','&quot;')+'" maxlength="60"></label>').join('');$('#courseGrid').innerHTML=courses.map(c=>'<a class="parent-course '+(c[3]?'ready':'review')+'" href="'+c[2]+'"><small>PATH '+c[0]+'</small><strong>'+c[1]+'</strong><span>'+(c[3]?'Ready now':'Built · family review')+'</span></a>').join('')}
$('#learner').value=learner;$('#learner').onchange=e=>{learner=e.target.value;localStorage.setItem(learnerKey,learner);render()};$('#saveRewards').onclick=()=>{const d={};document.querySelectorAll('[data-reward]').forEach(i=>d[i.dataset.reward]=i.value.trim()||'Family reward');localStorage.setItem(rewardKey,JSON.stringify(d));$('#rewardSaved').textContent=' Saved.';render()};render();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
